import { Language } from '../../localization/translations';

interface StoryTranslations {
  title: string;
  description: string;
  author: string;
  nodes: {
    [nodeId: string]: {
      title: string;
      narration: string;
      choices: {
        [choiceId: string]: {
          text: string;
        };
      };
    };
  };
}

// Helper function to generate story nodes
function createStoryNode(nodeId: string, title: string, narration: string, choice1?: string, choice2?: string): any {
  const node: any = { title, narration, choices: {} };
  if (choice1) node.choices[`${nodeId.replace(/-\d+$/, '')}-c${parseInt(nodeId.split('-')[2]) * 2 - 1}`] = { text: choice1 };
  if (choice2) node.choices[`${nodeId.replace(/-\d+$/, '')}-c${parseInt(nodeId.split('-')[2]) * 2}`] = { text: choice2 };
  return node;
}

